242	    /**
243	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when the
244	     * postcode is absent, not 4 digits, or in no known range.
245	     *
246	     * @param postcode the owner's postcode, may be {@code null}
247	     * @return the region code, or {@code null} when no known range contains the postcode
248	     */
249	    private String regionFromPostcode(String postcode) {
250	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
251	            return null;
252	        }
253	        int value = Integer.parseInt(postcode);
254	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
255	            int[] range = entry.getValue();
256	            if (value >= range[0] && value <= range[1]) {
257	                return entry.getKey();
258	            }
259	        }
260	        return null;
261	    }
