356	            .filter(existing -> equalsIgnoreCase(existing.getLastName(), owner.getLastName())
357	                && owner.getPostcode().equals(existing.getPostcode())
358	                && !equalsIgnoreCase(existing.getTelephone(), owner.getTelephone()))
359	            .min(Comparator.comparing(Owner::getId))
360	            .orElse(null);
