413	    /**
414	     * Rolls a registration date forward onto a business day: when it falls on a Saturday or Sunday
415	     * it advances to the following Monday, otherwise it is returned unchanged. Applied to the
416	     * effective registration date (whether supplied in the request or defaulted to the server date)
417	     * so a weekend value never persists as an owner's {@code registrationDate}.
418	     *
419	     * @param date the effective registration date
420	     * @return the same date when it is a weekday, otherwise the next Monday
421	     */
422	    private LocalDate toBusinessDay(LocalDate date) {
423	        return switch (date.getDayOfWeek()) {
424	            case SATURDAY -> date.plusDays(2);
425	            case SUNDAY -> date.plusDays(1);
426	            default -> date;
427	        };
428	    }
