468	    /**
469	     * The fixed inclusive 4-digit postcode range allowed for each region, keyed by region code
470	     * (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099).
471	     */
472	    private static final Map<String, int[]> REGION_POSTCODE_RANGES = Map.of(
473	        "NSW", new int[] {2000, 2099},
474	        "VIC", new int[] {3000, 3099},
475	        "QLD", new int[] {4000, 4099});
