477	    /**
478	     * Validates an owner's postcode, but only when one is supplied. A {@code null} or blank postcode
479	     * is optional and accepted, keeping the create contract backward-compatible. When present the
480	     * value must be 4 digits and, when the owner's city has a known region (Sydney->NSW,
481	     * Melbourne->VIC, Brisbane->QLD), must fall within that region's inclusive range (NSW 2000-2099,
482	     * VIC 3000-3099, QLD 4000-4099). A city with no known region accepts any 4-digit postcode.
483	     *
484	     * @param postcode the raw postcode value as submitted, may be {@code null}
485	     * @param city     the owner's city, used to resolve the region whose range applies
486	     * @throws InvalidPostcodeException if a supplied postcode is not 4 digits or is out of range for
487	     *                                  the city's region
488	     */
489	    private void validatePostcode(String postcode, String city) {
490	        if (isBlank(postcode)) {
491	            return;
492	        }
493	        if (!postcode.matches("[0-9]{4}")) {
494	            throw new InvalidPostcodeException(postcode, city);
495	        }
496	        String region = region(city);
497	        int[] range = region == null ? null : REGION_POSTCODE_RANGES.get(region);
498	        if (range != null) {
499	            int value = Integer.parseInt(postcode);
500	            if (value < range[0] || value > range[1]) {
501	                throw new InvalidPostcodeException(postcode, city);
502	            }
503	        }
504	    }
