506	    /**
507	     * Derives an owner's region from its city using the fixed city-to-region table (Sydney->NSW,
508	     * Melbourne->VIC, Brisbane->QLD), returning {@code null} when the city is not in the table.
509	     *
510	     * @param city the owner's city
511	     * @return the region code, or {@code null} when the city has no known region
512	     */
513	    private String region(String city) {
514	        if (city == null) {
515	            return null;
516	        }
517	        return switch (city) {
518	            case "Sydney" -> "NSW";
519	            case "Melbourne" -> "VIC";
520	            case "Brisbane" -> "QLD";
521	            default -> null;
522	        };
523	    }
