525	    /**
526	     * The number of national (subscriber) digits an E.164 number must carry for a given country
527	     * calling code, keyed by that code (without the leading '+'). Australia ('+61') requires 9
528	     * national digits and the North American Numbering Plan ('+1') requires 10.
529	     */
530	    private static final Map<String, Integer> NATIONAL_NUMBER_LENGTHS =
531	        Map.of("61", 9, "1", 10);
532	
533	    /**
534	     * Normalizes a submitted telephone into E.164 form. Spaces, dashes and brackets are stripped.
535	     * A leading '+' with its country code is kept; otherwise the country code '+61' is assumed and
536	     * a single leading '0' is dropped from the national digits. The resulting value must be a '+'
537	     * followed by 8 to 15 digits, and its national-number length must match the one required by its
538	     * country calling code ('+61' requires 9 national digits, '+1' requires 10).
539	     *
540	     * @param telephone the raw telephone value as submitted
541	     * @return the E.164 normalized telephone (e.g. {@code +61412345678})
542	     * @throws InvalidTelephoneException if the value cannot form a valid E.164 number, or its
543	     *                                   national-number length is wrong for its country code
544	     */
545	    private String normalizeTelephone(String telephone) {
546	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
547	        String nationalSignificantNumber;
548	        if (cleaned.startsWith("+")) {
549	            nationalSignificantNumber = cleaned.substring(1);
550	        } else {
551	            String national = cleaned.startsWith("0") ? cleaned.substring(1) : cleaned;
552	            nationalSignificantNumber = "61" + national;
553	        }
554	        if (!nationalSignificantNumber.matches("[0-9]{8,15}")) {
555	            throw new InvalidTelephoneException(telephone);
556	        }
557	        validateNationalNumberLength(nationalSignificantNumber, telephone);
558	        return "+" + nationalSignificantNumber;
559	    }
560	
561	    /**
562	     * Validates the national-number length of an E.164 number against its country calling code. The
563	     * significant number is a country code immediately followed by the national digits; for each
564	     * known code in {@link #NATIONAL_NUMBER_LENGTHS} the remaining national digits must number
565	     * exactly the required amount ('+61' requires 9, '+1' requires 10). Codes with no known rule are
566	     * left unchecked.
567	     *
568	     * @param nationalSignificantNumber the E.164 digits following the '+' (country code + national)
569	     * @param rejectedValue             the raw telephone value, reported on rejection
570	     * @throws InvalidTelephoneException if the national-number length is wrong for the country code
571	     */
572	    private void validateNationalNumberLength(String nationalSignificantNumber, String rejectedValue) {
573	        for (Map.Entry<String, Integer> rule : NATIONAL_NUMBER_LENGTHS.entrySet()) {
574	            String countryCode = rule.getKey();
575	            if (nationalSignificantNumber.startsWith(countryCode)) {
576	                int nationalDigits = nationalSignificantNumber.length() - countryCode.length();
577	                if (nationalDigits != rule.getValue()) {
578	                    throw new InvalidTelephoneException(rejectedValue);
579	                }
580	                return;
581	            }
582	        }
583	    }
