585	    /**
586	     * Normalizes a submitted email. An owner may omit the email entirely (a {@code null} or blank
587	     * value is treated as absent and returns {@code null}); when present the value must be a
588	     * syntactically valid address, and is stored and returned lower-cased.
589	     *
590	     * @param email the raw email value as submitted, may be {@code null}
591	     * @return the lower-cased email, or {@code null} when none was supplied
592	     * @throws InvalidEmailException if a non-blank value is not a syntactically valid address
593	     */
594	    private String normalizeEmail(String email) {
595	        if (email == null || email.isBlank()) {
596	            return null;
597	        }
598	        String normalized = email.trim().toLowerCase();
599	        if (!EMAIL_PATTERN.matcher(normalized).matches()) {
600	            throw new InvalidEmailException(email);
601	        }
602	        String domain = normalized.substring(normalized.lastIndexOf('@') + 1);
603	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
604	            throw new DisposableEmailException(email);
605	        }
606	        return normalized;
607	    }
