609	    /**
610	     * The single, consolidated duplicate check. Rejects the owner being created when its whole
611	     * {@link #identityKey(Owner) identityKey} exactly equals that of an existing owner. Because the
612	     * key is the normalized telephone, email and householdId joined together, this one check
613	     * subsumes the former separate telephone, email and household duplicate rules: only an exact
614	     * full-key match counts as a duplicate, so two members of the same household (same householdId)
615	     * with different telephones have different keys and are both allowed.
616	     *
617	     * @param owner the owner being created, with its normalized telephone, email and householdId
618	     *              already applied
619	     * @throws DuplicateIdentityException if another owner already has the same identityKey
620	     */
621	    private void rejectDuplicateIdentity(Owner owner) {
622	        String identityKey = identityKey(owner);
623	        boolean inUse = this.clinicService.findAllOwners().stream()
624	            .map(this::identityKey)
625	            .anyMatch(identityKey::equals);
626	        if (inUse) {
627	            throw new DuplicateIdentityException(identityKey);
628	        }
629	    }
