631	    /**
632	     * Derives an owner's {@code identityKey}: {@code normalizedTelephone + '|' + (email or empty) +
633	     * '|' + householdId}. A {@code null} email or householdId contributes an empty segment. Every
634	     * duplicate decision is made by comparing whole identityKeys.
635	     *
636	     * @param owner the owner whose identityKey to derive
637	     * @return the derived identityKey
638	     */
639	    private String identityKey(Owner owner) {
640	        String telephone = owner.getTelephone() == null ? "" : owner.getTelephone();
641	        String email = owner.getEmail() == null ? "" : owner.getEmail();
642	        String householdId = owner.getHouseholdId() == null ? "" : owner.getHouseholdId();
643	        return telephone + "|" + email + "|" + householdId;
644	    }
