646	    /**
647	     * Applies the household rule to an owner being created. The household is keyed on
648	     * (lastName, postcode): the owner is assigned the deterministic {@link #householdId(Owner)
649	     * householdId} derived from its normalized lastName and postcode, so owners sharing a lastName
650	     * and postcode automatically share the identifier — the link is computed, not created by a flag.
651	     *
652	     * <p>Because the household is keyed on (lastName, postcode), any existing owner that derives the
653	     * same householdId is a member of the same household, and a second owner joining it is a
654	     * household duplicate. Such a create is rejected with 409 unless the request declares
655	     * {@code sharesHousehold=true}, in which case it is allowed through as a declared household
656	     * member. The {@code sharesHousehold} directive only bypasses this duplicate block.
657	     *
658	     * @param owner           the owner being created
659	     * @param sharesHousehold whether the request declared it shares a household, bypassing the block
660	     * @throws HouseholdDuplicateException if an existing owner already shares the household and the
661	     *                                     request did not declare {@code sharesHousehold=true}
662	     */
663	    private void applyHousehold(Owner owner, boolean sharesHousehold) {
664	        String householdId = householdId(owner);
665	        owner.setHouseholdId(householdId);
666	        boolean householdExists = this.clinicService.findAllOwners().stream()
667	            .anyMatch(existing -> householdId.equals(householdId(existing)));
668	        if (householdExists && !sharesHousehold) {
669	            throw new HouseholdDuplicateException(householdId);
670	        }
671	    }
672	
673	    /**
674	     * Derives the stable, shared household identifier for an owner, formatted {@code HH-<HEX12>}
675	     * where HEX12 is the first 12 upper-cased hex characters of the SHA-256 of the owner's normalized
676	     * lastName, a {@code '|'} separator, and its postcode. Being a pure function of (lastName,
677	     * postcode), every owner sharing a lastName and postcode derives the same value regardless of
678	     * creation order. A {@code null} postcode contributes an empty segment.
679	     *
680	     * @param owner the owner whose household identifier to derive
681	     * @return the household identifier
682	     */
683	    private String householdId(Owner owner) {
684	        String lastNameKey = toHouseholdKey(owner.getLastName());
685	        String postcode = owner.getPostcode() == null ? "" : owner.getPostcode();
686	        try {
687	            byte[] digest = MessageDigest.getInstance("SHA-256")
688	                .digest((lastNameKey + "|" + postcode).getBytes(StandardCharsets.UTF_8));
689	            StringBuilder hex = new StringBuilder(digest.length * 2);
690	            for (byte b : digest) {
691	                hex.append(String.format("%02x", b));
692	            }
693	            return "HH-" + hex.substring(0, 12).toUpperCase(Locale.ROOT);
694	        } catch (NoSuchAlgorithmException ex) {
695	            throw new IllegalStateException("SHA-256 not available", ex);
696	        }
697	    }
698	
699	    /**
700	     * Normalizes a lastName or address for household comparison: leading and trailing whitespace is
701	     * trimmed, internal runs of whitespace are collapsed to a single space, and the value is
702	     * lower-cased so the comparison is case-insensitive. A {@code null} value normalizes to an empty
703	     * string.
704	     */
705	    private String toHouseholdKey(String value) {
706	        if (value == null) {
707	            return "";
708	        }
709	        return value.trim().replaceAll("\\s+", " ").toLowerCase(Locale.ROOT);
710	    }
711	
712	    /**
713	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
714	     * leading and trailing whitespace is trimmed, internal runs of whitespace are collapsed to a
715	     * single space, the value is upper-cased, and common street-type abbreviations are expanded on a
716	     * whole-word basis ({@code ST->STREET}, {@code RD->ROAD}, {@code AVE->AVENUE}). A {@code null}
717	     * value, or one that is blank once trimmed, normalizes to an empty string.
718	     *
719	     * @param address the raw address value as submitted, may be {@code null}
720	     * @return the normalized address, or an empty string when none was supplied
721	     */
722	    private String normalizeAddress(String address) {
723	        if (address == null) {
724	            return "";
725	        }
726	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(Locale.ROOT);
727	        if (collapsed.isEmpty()) {
728	            return "";
729	        }
730	        String[] tokens = collapsed.split(" ");
731	        StringBuilder normalized = new StringBuilder(collapsed.length());
732	        for (int i = 0; i < tokens.length; i++) {
733	            if (i > 0) {
734	                normalized.append(' ');
735	            }
736	            normalized.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
737	        }
738	        return normalized.toString();
739	    }
