742	    @Override
743	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
744	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
745	        if (currentOwner == null) {
746	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
747	        }
748	        currentOwner.setAddress(ownerFieldsDto.getAddress());
749	        currentOwner.setCity(ownerFieldsDto.getCity());
750	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
751	        currentOwner.setLastName(ownerFieldsDto.getLastName());
752	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
753	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
754	        this.clinicService.saveOwner(currentOwner);
755	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
756	    }
757	
758	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
759	    @Transactional
760	    @Override
761	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
762	        Owner owner = this.clinicService.findOwnerById(ownerId);
763	        if (owner == null) {
764	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
765	        }
766	        this.clinicService.deleteOwner(owner);
767	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
768	    }
769	
770	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
771	    @Override
772	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
773	        Owner owner = this.clinicService.findOwnerById(ownerId);
774	        if (owner == null) {
775	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
776	        }
