780	        pet.setOwner(owner);
781	        pet.getType().setName(null);
782	        this.clinicService.savePet(pet);
783	        PetDto petDto = petMapper.toPetDto(pet);
784	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
785	            .buildAndExpand(pet.getId()).toUri());
786	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
787	    }
788	
789	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
