138	    /**
139	     * Derives the owner's locality (region) from the region-and-hash identity: it is the REGION
140	     * component of the owner's {@code customerCode} ({@code <REGION>-<HASH8>}), so the locality now
141	     * moves in lockstep with the identity assigned on create. When no customer code has been
142	     * assigned (e.g. seed data) the region is derived directly, preferring the postcode: a 4-digit
143	     * postcode falling in a known region's range (NSW 2000-2099, VIC 3000-3099, QLD 4000-4099)
144	     * yields that region, otherwise the city-to-region table (Sydney->NSW, Melbourne->VIC,
145	     * Brisbane->QLD) is consulted, returning {@code UNKNOWN} when neither identifies a region.
146	     */
147	    protected String locality(Owner owner) {
148	        String customerCode = owner.getCustomerCode();
149	        if (customerCode != null) {
150	            int dash = customerCode.indexOf('-');
151	            if (dash > 0) {
152	                return customerCode.substring(0, dash);
153	            }
154	        }
155	        String fromPostcode = regionFromPostcode(owner.getPostcode());
156	        if (fromPostcode != null) {
157	            return fromPostcode;
158	        }
159	        String city = owner.getCity();
160	        if (city == null) {
161	            return "UNKNOWN";
162	        }
163	        return switch (city) {
164	            case "Sydney" -> "NSW";
165	            case "Melbourne" -> "VIC";
166	            case "Brisbane" -> "QLD";
167	            default -> "UNKNOWN";
168	        };
169	    }
170	
171	    /**
172	     * The IANA timezone of each region, keyed by region code (NSW->Australia/Sydney,
173	     * VIC->Australia/Melbourne, QLD->Australia/Brisbane).
174	     */
175	    private static final Map<String, String> REGION_TIMEZONE = Map.of(
176	        "NSW", "Australia/Sydney",
177	        "VIC", "Australia/Melbourne",
178	        "QLD", "Australia/Brisbane");
179	
180	    /**
181	     * Derives the owner's {@code timezone}: the IANA timezone name for the owner's
182	     * {@link #locality(Owner) locality/region}, looked up in the fixed region-to-timezone table
183	     * (NSW->Australia/Sydney, VIC->Australia/Melbourne, QLD->Australia/Brisbane). Returns
184	     * {@code null} when the region has no known timezone (e.g. {@code UNKNOWN}).
185	     */
186	    protected String timezone(Owner owner) {
187	        return REGION_TIMEZONE.get(locality(owner));
188	    }
189	
190	    /**
191	     * Resolves the region whose postcode range contains the given postcode, or {@code null} when
192	     * the postcode is absent, not 4 digits, or in no known range.
193	     */
194	    private String regionFromPostcode(String postcode) {
195	        if (postcode == null || !postcode.matches("[0-9]{4}")) {
196	            return null;
197	        }
198	        int value = Integer.parseInt(postcode);
199	        for (Map.Entry<String, int[]> entry : REGION_POSTCODE_RANGES.entrySet()) {
200	            int[] range = entry.getValue();
201	            if (value >= range[0] && value <= range[1]) {
202	                return entry.getKey();
203	            }
204	        }
205	        return null;
206	    }
207	
208	    /**
209	     * The minimum household size (counting the owner itself) that earns household membership
210	     * points.
211	     */
212	    private static final int HOUSEHOLD_POINTS_SIZE = 3;
213	
214	    /**
215	     * An owner must have been registered for strictly more than this many days to earn the
216	     * tenure membership points. A newly created owner has zero tenure and so never clears this
217	     * threshold.
218	     */
219	    private static final int TENURE_POINTS_DAYS = 365;
220	
221	    /**
222	     * Derives the owner's membership points: it starts at 0, gains 2 when an email is present,
223	     * gains 1 when the owner has no namesakes (namesakeCount is 0), gains 2 when the owner's
224	     * household has {@value #HOUSEHOLD_POINTS_SIZE} or more members, and gains 3 once the owner's
225	     * tenure exceeds {@value #TENURE_POINTS_DAYS} days.
226	     */
227	    protected Integer membershipPoints(Owner owner) {
228	        int points = 0;
229	        boolean hasEmail = owner.getEmail() != null && !owner.getEmail().isBlank();
230	        if (hasEmail) {
231	            points += 2;
232	        }
233	        boolean noNamesakes = owner.getNamesakeCount() != null && owner.getNamesakeCount() == 0;
234	        if (noNamesakes) {
235	            points += 1;
236	        }
237	        if (householdSize(owner) >= HOUSEHOLD_POINTS_SIZE) {
238	            points += 2;
239	        }
240	        if (tenureDays(owner) > TENURE_POINTS_DAYS) {
241	            points += 3;
242	        }
243	        return points;
244	    }
245	
246	    /**
247	     * Derives the owner's membership level from their {@link #membershipPoints(Owner) membership
248	     * points}: level 1 for 0-1 points, level 2 for 2-3, level 3 for 4-5, and level 4 for 6 or more.
249	     */
250	    protected Integer membershipLevel(Owner owner) {
251	        int points = membershipPoints(owner);
252	        if (points <= 1) {
253	            return 1;
254	        }
255	        if (points <= 3) {
256	            return 2;
257	        }
258	        if (points <= 5) {
259	            return 3;
260	        }
261	        return 4;
262	    }
263	
264	    /**
265	     * The number of owners in this owner's household — the count of owners (including this one)
266	     * sharing its {@code householdId}. Returns 0 when the owner has no household identifier.
267	     */
268	    private long householdSize(Owner owner) {
269	        String householdId = owner.getHouseholdId();
270	        if (householdId == null) {
271	            return 0;
272	        }
273	        return this.clinicService.findAllOwners().stream()
274	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
275	            .count();
276	    }
277	
278	    /**
279	     * The owner's tenure in whole days: the number of days from their {@code registrationDate} up to
280	     * the current date. Returns 0 when no registration date is present, so an owner without a
281	     * registration date is treated as having no tenure.
282	     */
283	    private long tenureDays(Owner owner) {
284	        LocalDate registrationDate = owner.getRegistrationDate();
285	        if (registrationDate == null) {
286	            return 0;
287	        }
288	        return ChronoUnit.DAYS.between(registrationDate, LocalDate.now());
289	    }
290	
291	    /**
292	     * Flags a bulk-signup day: {@code true} once more than {@link #BULK_SIGNUP_THRESHOLD} other
293	     * owners already carry this owner's {@code registrationDate}. The owner itself is excluded from
294	     * the count, so on a create the flag reflects the owners that pre-existed it that day, matching
295	     * the accumulation the per-day create limit is enforced against. Returns {@code false} when the
296	     * owner has no registration date.
297	     */
298	    protected Boolean bulkSignupWarning(Owner owner) {
299	        LocalDate registrationDate = owner.getRegistrationDate();
300	        if (registrationDate == null) {
301	            return false;
302	        }
303	        long othersOnDay = this.clinicService.findAllOwners().stream()
304	            .filter(existing -> !Objects.equals(existing.getId(), owner.getId()))
305	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
306	            .count();
307	        return othersOnDay > BULK_SIGNUP_THRESHOLD;
308	    }
309	
310	    /**
311	     * Derives the owner's {@code checkDigit}: the Luhn check digit (0-9) computed over the digits
312	     * contained in the owner's {@code customerCode}. Non-digit characters are ignored. Returns
313	     * {@code null} when no customer code has been assigned.
314	     */
315	    protected Integer checkDigit(Owner owner) {
316	        String customerCode = owner.getCustomerCode();
317	        if (customerCode == null) {
318	            return null;
319	        }
320	        int sum = 0;
321	        boolean dbl = true;
322	        for (int i = customerCode.length() - 1; i >= 0; i--) {
323	            char c = customerCode.charAt(i);
324	            if (c < '0' || c > '9') {
325	                continue;
326	            }
327	            int d = c - '0';
328	            if (dbl) {
329	                d *= 2;
330	                if (d > 9) {
331	                    d -= 9;
332	                }
333	            }
334	            sum += d;
335	            dbl = !dbl;
336	        }
337	        return (10 - (sum % 10)) % 10;
338	    }
339	
340	    public abstract Owner toOwner(OwnerDto ownerDto);
341	
342	    @Mapping(target = "id", ignore = true)
343	    @Mapping(target = "pets", ignore = true)
344	    public abstract Owner toOwner(OwnerFieldsDto ownerDto);
345	
346	    public abstract List<OwnerDto> toOwnerDtoCollection(Collection<Owner> ownerCollection);
347	
348	    public abstract Collection<Owner> toOwners(Collection<OwnerDto> ownerDtos);
349	
