351	        OwnerPageDto ownerPageDto = new OwnerPageDto();
352	        ownerPageDto.setContent(toOwnerDtoCollection(ownerPage.getContent()));
353	        ownerPageDto.setPage(ownerPage.getNumber());
354	        ownerPageDto.setSize(ownerPage.getSize());
355	        ownerPageDto.setTotalElements(ownerPage.getTotalElements());
356	        ownerPageDto.setTotalPages(ownerPage.getTotalPages());
